-- Seed core D&D 5e SRD Spells in Portuguese
insert into public.spells (user_id, system, name, level, school, casting_time, range, components, duration, description, is_homebrew) values
-- Truques (Cantrips)
(null, 'dnd5e', 'Mão de Mago', 0, 'Conjuração', '1 ação', '9 metros', 'V, S', '1 minuto', 'Uma mão espectral e flutuante aparece em um ponto de sua escolha dentro do alcance. A mão permanece pela duração ou até você descartá-la com uma ação. A mão desaparece se estiver a mais de 9 metros de você ou se você a conjurar novamente. Você pode usar sua ação para controlar a mão para manipular um objeto, abrir uma porta ou contêiner destrancado, guardar ou recuperar um item de um contêiner aberto, ou derramar o conteúdo de um frasco.', false),
(null, 'dnd5e', 'Prestidigitação', 0, 'Transmutação', '1 ação', '3 metros', 'V, S', 'Até 1 hora', 'Esta magia é um truque mágico simples que conjuradores iniciantes usam para praticar. Você cria um dos seguintes efeitos mágicos dentro do alcance: cria um efeito sensorial instantâneo e inofensivo; acende ou apaga uma vela, tocha ou pequena fogueira; limpa ou suja um objeto de até 1 metro cúbico; esquenta, esfria ou tempera até 1 metro cúbico de matéria não-viva por 1 hora; faz aparecer um símbolo ou marca em uma superfície por 1 hora; ou cria uma bugiganga ilusória que cabe na sua mão e dura até o final do seu próximo turno.', false),
(null, 'dnd5e', 'Raio de Fogo', 0, 'Evocação', '1 ação', '36 metros', 'V, S', 'Instantânea', 'Você arremessa uma centelha de fogo em uma criatura ou objeto dentro do alcance. Faça um ataque de magia à distância contra o alvo. Se atingir, o alvo sofre 1d10 de dano de fogo. Um objeto inflamável atingido por esta magia incendeia se não estiver sendo usado ou carregado. O dano aumenta em 1d10 quando você atinge o 5º nível (2d10), 11º nível (3d10) e 17º nível (4d10).', false),
(null, 'dnd5e', 'Orientação', 0, 'Adivinhação', '1 ação', 'Toque', 'V, S', 'Concentração, até 1 minuto', 'Você toca uma criatura voluntária. Uma vez antes da magia acabar, o alvo pode rolar um d4 e adicionar o número rolado a um teste de habilidade de sua escolha. Ele pode rolar o dado antes ou depois de realizar o teste de habilidade. A magia então se encerra.', false),
(null, 'dnd5e', 'Ilusão Menor', 0, 'Ilusão', '1 ação', '9 metros', 'S, M (um pedaço de lã)', '1 minuto', 'Você cria um som ou uma imagem de um objeto dentro do alcance que dura pela duração. A ilusão também termina se você a descartar com uma ação ou conjurar esta magia novamente. Se você criar um som, seu volume pode variar de um sussurro a um grito. Se você criar uma imagem de um objeto, ela deve caber em um cubo de 1,5 metro. A imagem não pode criar som, luz, cheiro ou qualquer outro efeito físico.', false),

-- 1º Nível
(null, 'dnd5e', 'Mísseis Mágicos', 1, 'Evocação', '1 ação', '36 metros', 'V, S', 'Instantânea', 'Você cria três dardos brilhantes de força mágica. Cada dardo atinge uma criatura de sua escolha que você possa ver dentro do alcance. Um dardo causa 1d4 + 1 de dano de força ao seu alvo. Os dardos atingem simultaneamente e você pode direcioná-los para atingir uma única criatura ou várias. Para cada nível de conjuração acima do 1º, a magia cria um dardo adicional.', false),
(null, 'dnd5e', 'Armadura de Mago', 1, 'Abjuração', '1 ação', 'Toque', 'V, S, M (um pedaço de couro curado)', '8 horas', 'Você toca uma criatura voluntária que não esteja vestindo armadura. Uma força mágica protetora a envolve até que a magia acabe. A CA base do alvo torna-se 13 + seu modificador de Destreza. A magia acaba se o alvo vestir uma armadura ou se você descartar a magia com uma ação.', false),
(null, 'dnd5e', 'Curar Ferimentos', 1, 'Evocação', '1 ação', 'Toque', 'V, S', 'Instantânea', 'Uma criatura que você toca recupera um número de pontos de vida igual a 1d8 + seu modificador de habilidade de conjuração. Esta magia não tem efeito sobre mortos-vivos ou constructos. Conjurar esta magia usando um espaço de magia de 2º nível ou superior aumenta a cura em 1d8 para cada nível acima do 1º.', false),
(null, 'dnd5e', 'Palavra Curativa', 1, 'Evocação', '1 ação bônus', '18 metros', 'V', 'Instantânea', 'Uma criatura de sua escolha que você possa ver dentro do alcance recupera pontos de vida iguais a 1d4 + seu modificador de habilidade de conjuração. Esta magia não tem efeito sobre mortos-vivos ou constructos. Em níveis superiores, a cura aumenta em 1d4 para cada nível acima do 1º.', false),
(null, 'dnd5e', 'Escudo', 1, 'Abjuração', '1 reação (quando atingido)', 'Pessoal', 'V, S', '1 rodada', 'Uma barreira invisível de força mágica surge para protegê-lo. Até o início do seu próximo turno, você recebe um bônus de +5 na sua CA (inclusive contra o ataque que engatilhou a reação) e você não sofre dano de Mísseis Mágicos.', false),
(null, 'dnd5e', 'Onda de Choque', 1, 'Evocação', '1 ação', 'Pessoal (cubo de 4,5m)', 'V, S', 'Instantânea', 'Uma onda de força mental varre a partir de você. Cada criatura em um cubo de 4,5 metros centrado em você deve realizar um teste de salvaguarda de Constituição. Se falhar, sofre 2d8 de dano trovejante e é empurrada 3 metros para longe de você. Se passar, sofre metade do dano. Objetos soltos são empurrados automaticamente.', false),
(null, 'dnd5e', 'Detectar Magia', 1, 'Adivinhação', '1 ação', 'Pessoal', 'V, S', 'Concentração, até 10 minutos', 'Pela duração, você percebe a presença de magia a até 9 metros de você. Se você perceber magia dessa forma, você pode usar sua ação para ver uma aura tênue ao redor de qualquer criatura ou objeto visível na área que carregue magia, e você aprende a sua escola de magia, se houver.', false),

-- 2º Nível
(null, 'dnd5e', 'Passo Nebuloso', 2, 'Conjuração', '1 ação bônus', 'Pessoal', 'V', 'Instantânea', 'Envolto por uma névoa prateada momentânea, você se teletransporta a até 9 metros para um espaço desocupado que você possa ver.', false),
(null, 'dnd5e', 'Invisibilidade', 2, 'Ilusão', '1 ação', 'Toque', 'V, S, M (um cílio envolto em goma-arábica)', 'Concentração, até 1 hora', 'Uma criatura que você toca torna-se invisível até a magia acabar. Qualquer coisa que o alvo esteja vestindo ou carregando fica invisível com ele. A magia acaba mais cedo se o alvo atacar ou conjurar uma magia.', false),
(null, 'dnd5e', 'Sugestão', 2, 'Encantamento', '1 ação', '9 metros', 'V, M (uma língua de cobra e mel)', 'Concentração, até 8 horas', 'Você sugere um curso de atividade (limitado a uma frase ou duas) e influencia magicamente uma criatura dentro do alcance que possa ver e ouvir você, e que compreenda seu idioma. A sugestão deve ser formulada de modo a parecer razoável. O alvo deve fazer um teste de salvaguarda de Sabedoria; se falhar, ele segue o curso de ação sugerido.', false),
(null, 'dnd5e', 'Imobilizar Pessoa', 2, 'Encantamento', '1 ação', '18 metros', 'V, S, M (uma peça de ferro reta)', 'Concentração, até 1 minuto', 'Escolha um humanoide que você possa ver dentro do alcance. O alvo deve ser bem-sucedido em um teste de salvaguarda de Sabedoria ou ficará paralisado pela duração. Ao final de cada um dos turnos dele, o alvo pode realizar outra salvaguarda para encerrar o efeito.', false),
(null, 'dnd5e', 'Restauração Menor', 2, 'Abjuração', '1 ação', 'Toque', 'V, S', 'Instantânea', 'Você toca uma criatura e encerra uma doença ou uma condição que a esteja afligindo. A condição pode ser cego, surdo, paralisado ou envenenado.', false),

-- 3º Nível
(null, 'dnd5e', 'Bola de Fogo', 3, 'Evocação', '1 ação', '45 metros', 'V, S, M (uma esfera de fezes de morcego e enxofre)', 'Instantânea', 'Um feixe brilhante salta da ponta do seu dedo indicador para um ponto de sua escolha dentro do alcance e então irrompe com um rugido baixo em uma explosão de chamas. Cada criatura em uma esfera de 6 metros de raio centrada no ponto escolhido deve fazer um teste de salvaguarda de Destreza. Uma criatura sofre 8d6 de dano de fogo se falhar na salvaguarda, ou metade se passar. O fogo se espalha dobrando esquinas e incendeia objetos inflamáveis.', false),
(null, 'dnd5e', 'Contrafeitiço', 3, 'Abjuração', '1 reação (ao ver magia)', '18 metros', 'S', 'Instantânea', 'Você tenta interromper uma criatura no processo de conjurar uma magia. Se a criatura estiver conjurando uma magia de 3º nível ou inferior, a magia falha e não surte efeito. Se for de 4º nível ou superior, faça um teste de atributo chave contra CD 10 + nível da magia para anulá-la.', false),
(null, 'dnd5e', 'Dissipar Magia', 3, 'Abjuração', '1 ação', '36 metros', 'V, S', 'Instantânea', 'Escolha uma criatura, objeto ou efeito mágico dentro do alcance. Qualquer magia de 3º nível ou inferior no alvo termina. Para cada magia de 4º nível ou superior no alvo, faça um teste de atributo chave de conjuração (CD = 10 + o nível da magia). Se obtiver sucesso, a magia termina.', false),
(null, 'dnd5e', 'Voo', 3, 'Transmutação', '1 ação', 'Toque', 'V, S, M (uma pena de asa de pássaro)', 'Concentração, até 10 minutos', 'Você toca uma criatura voluntária. O alvo ganha deslocamento de voo de 18 metros pela duração. Quando a magia acaba, se o alvo ainda estiver flutuando, ele cai a menos que tenha outra forma de se manter no ar.', false),
(null, 'dnd5e', 'Reviver', 3, 'Conjuração', '1 ação', 'Toque', 'V, S, M (diamantes valendo 300 PO)', 'Instantânea', 'Você toca uma criatura que tenha morrido no último minuto. Essa criatura retorna à vida com 1 ponto de vida. Esta magia não pode retornar à vida uma criatura que tenha morrido de velhice, nem pode restaurar membros perdidos.', false),
(null, 'dnd5e', 'Velocidade', 3, 'Transmutação', '1 ação', '9 metros', 'V, S, M (uma lasca de alcaçuz)', 'Concentração, até 1 minuto', 'Escolha uma criatura voluntária dentro do alcance. Até a magia acabar, o deslocamento do alvo é dobrado, ele ganha um bônus de +2 na CA, vantagem em salvaguardas de Destreza e ganha uma ação adicional em cada um de seus turnos (para atacar, disparar, esquivar, esconder ou usar objeto). Quando a magia acaba, o alvo fica exausto por 1 rodada.', false),

-- 4º Nível
(null, 'dnd5e', 'Metamorfose', 4, 'Transmutação', '1 ação', '18 metros', 'V, S, M (uma casca de casulo)', 'Concentração, até 1 hora', 'Esta magia transforma uma criatura que você possa ver dentro do alcance em uma nova forma. Uma criatura não-voluntária deve fazer um teste de salvaguarda de Sabedoria para evitar o efeito. A nova forma pode ser qualquer besta cujo ND seja menor ou igual ao nível/ND do alvo. Os atributos físicos e pontos de vida do alvo são substituídos pela nova criatura.', false),
(null, 'dnd5e', 'Porta Dimensional', 4, 'Conjuração', '1 ação', '150 metros', 'V', 'Instantânea', 'Você se teletransporta do seu local atual para qualquer outro local dentro do alcance. Você chega exatamente no local pretendido. Você pode trazer consigo objetos, desde que seu peso não exceda sua capacidade de carga, e uma criatura voluntária de tamanho Médio ou menor.', false),
(null, 'dnd5e', 'Banimento', 4, 'Abjuração', '1 ação', '18 metros', 'V, S, M (um item repulsivo)', 'Concentração, até 1 minuto', 'Você tenta enviar uma criatura que você possa ver dentro do alcance para outro plano de existência. O alvo deve fazer uma salvaguarda de Carisma. Se falhar, é banido. Se for nativo do plano atual, vai para um semiplano inofensivo; se for nativo de outro plano, retorna para lá.', false),

-- 5º Nível
(null, 'dnd5e', 'Dominar Pessoa', 5, 'Encantamento', '1 ação', '18 metros', 'V, S', 'Concentração, até 1 minuto', 'Você tenta tomar o controle de um humanoide que possa ver. O alvo deve passar em uma salvaguarda de Sabedoria com vantagem se estiver em combate com você. Se falhar, fica sob controle telepático completo das suas ações pela duração.', false),
(null, 'dnd5e', 'Curar Ferimentos em Massa', 5, 'Evocação', '1 ação', '18 metros', 'V, S', 'Instantânea', 'Uma onda de energia curativa emana de você. Escolha até seis criaturas em uma esfera de 9 metros de raio dentro do alcance. Cada alvo recupera pontos de vida iguais a 3d8 + seu modificador de habilidade de conjuração. Não afeta mortos-vivos ou constructos.', false),
(null, 'dnd5e', 'Reviver Mortos', 5, 'Necromancia', '1 hora', 'Toque', 'V, S, M (um diamante valendo 500 PO)', 'Instantânea', 'Você traz de volta à vida uma criatura morta que tenha falecido a no máximo 10 dias. O alvo retorna com todos os seus pontos de vida, curado de venenos e doenças não-mágicas, mas com uma penalidade de -4 em todas as jogadas (reduzida em 1 a cada descanso longo).', false),

-- 6º Nível
(null, 'dnd5e', 'Desintegrar', 6, 'Transmutação', '1 ação', '18 metros', 'V, S, M (uma pitada de poeira de ímã)', 'Instantânea', 'Um raio verde sai do seu dedo. Escolha uma criatura ou objeto visível no alcance. O alvo deve fazer uma salvaguarda de Destreza. Se falhar, sofre 10d6 + 40 de dano de força. Se este dano reduzir os pontos de vida do alvo a 0, ele é completamente reduzido a pó cinzento fino, destruindo corpos e itens mágicos ordinários.', false),
(null, 'dnd5e', 'Globo de Invulnerabilidade', 6, 'Abjuração', '1 ação', 'Pessoal (barreira de 3m)', 'V, S, M (uma conta de vidro)', 'Concentração, até 1 minuto', 'Uma barreira cintilante de 3 metros de raio surge ao seu redor. Qualquer magia de 5º nível ou inferior conjurada de fora da barreira não tem efeito sobre as criaturas dentro dela, mesmo se a magia for conjurada usando um espaço de nível superior.', false),

-- 7º Nível
(null, 'dnd5e', 'Teletransporte', 7, 'Conjuração', '1 ação', 'Ilimitado', 'V', 'Instantânea', 'Esta magia transporta instantaneamente você e até oito criaturas voluntárias para um destino que você conheça. Faça um teste de porcentagem (d100) baseado no quão familiarizado você está com o destino para determinar se a viagem foi bem-sucedida, se desviou do rumo ou se houve um acidente.', false),
(null, 'dnd5e', 'Dedo da Morte', 7, 'Necromancia', '1 ação', '18 metros', 'V, S', 'Instantânea', 'Você envia uma força negativa dolorosa através de uma criatura que possa ver dentro do alcance. O alvo deve realizar uma salvaguarda de Constituição. Sofre 7d8 + 30 de dano de necrose se falhar, ou metade se passar. Se o dano matar o alvo, ele se levanta no início do seu próximo turno como um zumbi sob seu comando.', false),

-- 8º Nível
(null, 'dnd5e', 'Dominar Monstro', 8, 'Encantamento', '1 ação', '18 metros', 'V, S', 'Concentração, até 1 hora', 'Semelhante a Dominar Pessoa, mas permite controlar telepaticamente qualquer tipo de criatura (monstros, dragões, gigantes, etc.). O alvo deve fazer uma salvaguarda de Sabedoria para evitar o controle.', false),
(null, 'dnd5e', 'Terremoto', 8, 'Evocação', '1 ação', '150 metros', 'V, S, M (um punhado de terra e argila)', 'Concentração, até 1 minuto', 'Você cria um tremor devastador no solo em um círculo de 45 metros de raio. O tremor derruba criaturas, quebra concentração de conjuradores, abre fendas profundas na terra e causa colapso de estruturas e construções civis dentro da área.', false),

-- 9º Nível
(null, 'dnd5e', 'Desejo', 9, 'Conjuração', '1 ação', 'Pessoal', 'V', 'Instantânea', 'Desejo é a magia mais poderosa que uma criatura mortal pode conjurar. Simplesmente ao falar em voz alta, você pode alterar a própria realidade. O uso básico desta magia é duplicar qualquer outra magia de 8º nível ou inferior sem precisar cumprir seus requisitos ou componentes. Você também pode desejar efeitos customizados sob grande estresse físico e risco de nunca mais poder conjurar Desejo.', false),
(null, 'dnd5e', 'Parar o Tempo', 9, 'Transmutação', '1 ação', 'Pessoal', 'V', 'Instantânea', 'Você para brevemente o fluxo do tempo para todos, exceto você. Você ganha 1d4 + 1 turnos consecutivos adicionais, durante os quais pode se mover e usar ações normalmente. A magia termina prematuramente se você realizar qualquer ação que afete outra criatura ou objeto carregado por ela.', false);
